from typing import List

class Solution:
    def isSolvable(self, words: List[str], result: str) -> bool:
        # Remove trailing spaces if any (problem examples have trailing spaces)
        words = [w.strip() for w in words]
        result = result.strip()

        # Collect all unique characters
        chars = set()
        for w in words:
            chars.update(w)
        chars.update(result)
        chars = list(chars)
        if len(chars) > 10:
            return False  # More than 10 unique chars can't map to digits 0-9

        # Leading characters cannot be zero
        leading_chars = set(w[0] for w in words if len(w) > 1)
        if len(result) > 1:
            leading_chars.add(result[0])

        # Precompute the factor for each character in the sum:
        # For example, SEND + MORE = MONEY
        # S contributes 1000 in SEND, M contributes 1000 in MORE, M contributes -10000 in MONEY
        char_factor = {c: 0 for c in chars}
        for w in words:
            length = len(w)
            for i, c in enumerate(w):
                char_factor[c] += 10 ** (length - i - 1)
        length = len(result)
        for i, c in enumerate(result):
            char_factor[c] -= 10 ** (length - i - 1)

        # Backtracking to assign digits to chars
        assigned = {}
        used_digits = set()

        def backtrack(i):
            if i == len(chars):
                # Check if sum is zero
                total = 0
                for c, f in char_factor.items():
                    total += assigned[c] * f
                return total == 0

            c = chars[i]
            for d in range(10):
                if d in used_digits:
                    continue
                if d == 0 and c in leading_chars:
                    continue
                assigned[c] = d
                used_digits.add(d)
                if backtrack(i + 1):
                    return True
                used_digits.remove(d)
                del assigned[c]
            return False

        return backtrack(0)

